static void RemoveICCProfileFromResourceBlock(StringInfo *icc_profile)
{
    size_t length = GetStringInfoLength(icc_profile);
    unsigned char *profile = GetStringInfoBody(icc_profile);
    size_t i = 0;

    while (i < length)
    {
        if (i + 12 > length)
            break;

        /* Read ICC profile ID */
        unsigned int signature = 0;
        signature = (unsigned int) profile[i] << 24;
        signature |= (unsigned int) profile[i + 1] << 16;
        signature |= (unsigned int) profile[i + 2] << 8;
        signature |= (unsigned int) profile[i + 3];

        if (signature == 0x0000040f)
        {
            size_t profile_size = (size_t) (profile[i + 4] << 24);
            profile_size |= (size_t) (profile[i + 5] << 16);
            profile_size |= (size_t) (profile[i + 6] << 8);
            profile_size |= (size_t) profile[i + 7];

            if (i + profile_size > length)
                break;

            /* Remove the ICC profile by shifting the memory */
            memmove(&profile[i], &profile[i + profile_size], length - i - profile_size);
            length -= profile_size;
            GetStringInfoBody(icc_profile)[length] = '\0';
            SetStringInfoLength(icc_profile, length);
            break;
        }

        /* Move to the next potential ICC profile */
        i += 12;
    }
}

